/*
Theme Name: Wordless
Theme URI: https://github.com/ola1de/Wordless-CMS
Author: Wordless
Author URI: https://github.com/ola1de/Wordless-CMS
Description: The default Wordless block theme — clean, fast and readable. Original work by the Wordless project; not a copy of any WordPress theme.
Requires at least: 1.0
Tested up to: 0.5
Requires PHP: 0
Version: 0.6.0
License: MIT
License URI: https://opensource.org/licenses/MIT
Text Domain: wordless
Tags: blog, clean, custom-colors, custom-menu, threaded-comments, wide-blocks
*/

/*
 * The theme.json-generated stylesheet (CSS custom properties, global
 * styles, per-block styles) is served with this file at /theme.css.
 * These rules are the theme's own hand-written layer on top of it.
 * Brand: deep teal ink, teal accent. System fonts only.
 */

a {
	text-decoration-thickness: 1px;
	text-underline-offset: 0.14em;
}

/* ---- header: sticky, translucent, blurred ---- */
.site-header {
	position: sticky;
	top: 0;
	z-index: 20;
	background: rgba(255, 255, 255, 0.88);
	backdrop-filter: blur(10px);
	border-bottom: 1px solid #e6edeb;
	padding: 1rem 1.5rem;
}

.site-header .wp-block-site-title {
	margin: 0;
	font-size: 1.375rem;
	font-weight: 800;
	letter-spacing: -0.01em;
}

.site-header .wp-block-site-title a {
	color: inherit;
	text-decoration: none;
}

.site-header .wp-block-site-tagline {
	margin: 0.125rem 0 0;
	color: var(--wp--preset--color--secondary);
	font-size: 0.875rem;
}

.site-header .wp-block-navigation ul {
	list-style: none;
	margin: 0.75rem 0 0;
	padding: 0;
	display: flex;
	gap: 0.375rem;
	flex-wrap: wrap;
}

.site-header .wp-block-navigation li a {
	display: inline-block;
	padding: 0.375rem 0.75rem;
	border-radius: 999px;
	color: var(--wp--preset--color--contrast);
	text-decoration: none;
	font-size: 0.9375rem;
	font-weight: 600;
}

.site-header .wp-block-navigation li a:hover {
	background: #f0f5f3;
	text-decoration: none;
}

/* ---- footer ---- */
.site-footer {
	border-top: 1px solid #e6edeb;
	padding: 1.5rem;
	color: var(--wp--preset--color--secondary);
	font-size: 0.875rem;
	text-align: center;
}

/* ---- post titles + content ---- */
.wp-block-post-title {
	letter-spacing: -0.02em;
}

.wp-block-post-title a {
	color: inherit;
	text-decoration: none;
}

.wp-block-post-title a:hover {
	color: var(--wp--preset--color--primary);
	text-decoration: none;
}

.wp-block-post-date {
	color: var(--wp--preset--color--secondary);
	font-size: 0.875rem;
}

.wp-block-post-excerpt {
	color: #3d4f48;
}

/* ---- query loop: each post is a card ---- */
.post-card {
	padding: 1.5rem;
	border: 1px solid #e6edeb;
	border-radius: 16px;
	background: #fff;
	box-shadow: 0 1px 2px rgba(6, 26, 30, 0.05);
	margin-bottom: 1rem;
	transition: box-shadow 0.15s ease, transform 0.15s ease, border-color 0.15s ease;
}

.post-card:hover {
	border-color: #c3d2cc;
	box-shadow: 0 6px 18px rgba(6, 26, 30, 0.08);
	transform: translateY(-1px);
}

.post-card .wp-block-post-title {
	margin: 0 0 0.375rem;
	font-size: 1.5rem;
	line-height: 1.3;
}

.post-card .wp-block-post-date {
	display: block;
	margin-bottom: 0.5rem;
}

.post-card .wp-block-post-excerpt {
	margin: 0;
}

/* ---- shop: product cards ---- */
.product-list {
	list-style: none;
	padding: 0;
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
	gap: 1rem;
}

.product-list li {
	padding: 1.5rem;
	border: 1px solid #e6edeb;
	border-radius: 16px;
	background: #fff;
	box-shadow: 0 1px 2px rgba(6, 26, 30, 0.05);
	transition: box-shadow 0.15s ease, transform 0.15s ease, border-color 0.15s ease;
}

.product-list li:hover {
	border-color: #c3d2cc;
	box-shadow: 0 6px 18px rgba(6, 26, 30, 0.08);
	transform: translateY(-1px);
}

.product-list h2 {
	margin: 0 0 0.375rem;
	font-size: 1.25rem;
	line-height: 1.3;
}

.product-list h2 a {
	color: inherit;
	text-decoration: none;
}

.product-list h2 a:hover {
	color: var(--wp--preset--color--primary);
	text-decoration: none;
}

.product-list .price {
	font-weight: 700;
	font-size: 1.125rem;
	margin: 0 0 0.5rem;
}

.product-list p {
	margin: 0 0 0.5rem;
}

.product-list p:last-child {
	margin-bottom: 0;
}

.wp-block-image img {
	border-radius: 12px;
}

.wp-block-quote {
	border-left: 3px solid var(--wp--preset--color--primary);
	background: #f4f8f7;
	border-radius: 0 12px 12px 0;
	padding: 1rem 1.25rem;
}

.wp-block-quote p {
	margin: 0;
}

/* ---- post list: cards ---- */
.post-list {
	list-style: none;
	padding: 0;
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.post-list li {
	padding: 1.5rem;
	border: 1px solid #e6edeb;
	border-radius: 16px;
	background: #fff;
	box-shadow: 0 1px 2px rgba(6, 26, 30, 0.05);
	transition: box-shadow 0.15s ease, transform 0.15s ease, border-color 0.15s ease;
}

.post-list li:hover {
	border-color: #c3d2cc;
	box-shadow: 0 6px 18px rgba(6, 26, 30, 0.08);
	transform: translateY(-1px);
}

.post-list h2 {
	margin: 0 0 0.375rem;
	font-size: 1.5rem;
	line-height: 1.3;
}

.post-list .meta {
	color: var(--wp--preset--color--secondary);
	font-size: 0.875rem;
	margin-bottom: 0.5rem;
}

/* ---- buttons + pagination ---- */
.wp-block-button__link {
	border-radius: 999px;
	padding: 0.625rem 1.25rem;
	font-weight: 600;
	box-shadow: 0 1px 2px rgba(6, 26, 30, 0.08);
}

.wp-block-button__link:hover {
	filter: brightness(0.95);
}

.pagination {
	margin-top: 2rem;
	display: flex;
	gap: 0.75rem;
	align-items: center;
}

.pagination a {
	display: inline-block;
	padding: 0.5rem 1rem;
	border: 1px solid #dde7e3;
	border-radius: 999px;
	text-decoration: none;
	font-weight: 600;
	font-size: 0.9375rem;
	background: #fff;
}

.pagination a:hover {
	border-color: var(--wp--preset--color--primary);
	text-decoration: none;
}

/* ---- comments ---- */
.comments {
	margin-top: 3rem;
	border-top: 1px solid #e6edeb;
	padding-top: 1.5rem;
}

.comments li {
	padding: 1rem 0;
	border-bottom: 1px solid #f0f5f3;
}

.comments .comment-meta {
	color: var(--wp--preset--color--secondary);
	font-size: 0.875rem;
}

form.comment-form label {
	display: block;
	margin: 0.75rem 0 0.375rem;
	font-weight: 600;
}

form.comment-form input,
form.comment-form textarea {
	width: 100%;
	box-sizing: border-box;
	padding: 0.625rem 0.75rem;
	border: 1px solid #c3d2cc;
	border-radius: 10px;
	font: inherit;
}

form.comment-form input:focus,
form.comment-form textarea:focus {
	outline: none;
	border-color: var(--wp--preset--color--primary);
	box-shadow: 0 0 0 3px rgba(13, 148, 136, 0.22);
}

form.comment-form button {
	margin-top: 1rem;
	padding: 0.625rem 1.25rem;
	background: var(--wp--preset--color--primary);
	color: #fff;
	border: 0;
	border-radius: 999px;
	font-weight: 600;
	cursor: pointer;
}

@media (max-width: 640px) {
	.site-header {
		padding: 0.875rem 1rem;
	}

	.post-list li {
		padding: 1.125rem;
	}
}

